async function save(){if(!selectedVehicle)return alert('Selecciona un vehículo.');if(!canManage())return alert('Tu perfil tiene acceso de consulta. Solo Almacén/Jefe de Almacén/Administrador puede actualizar el estado base.');const btn=$('base-save');btn.disabled=true;const old=btn.textContent;btn.textContent='Guardando...';try{const saved=await window.SkilledDB.saveVehicleBaseState(payload());if(saved){states.set(Number(selectedVehicle.id),saved);currentState=saved;damages=structuredClone(saved.danos||[])}setDirty(false);await renderHistory();render();alert('Estado base actualizado. Se utilizará como referencia en futuras responsivas del vehículo.')}catch(error){console.error(error);alert(error.message||'No se pudo guardar el estado base.')}finally{btn.disabled=false;btn.textContent=old}}
