function ensureReturnResponsibleSignatureV148(trip){const form=$('return-form');if(!form)return;let section=$('return-responsible-signature-v148');if(!section){section=document.createElement('section');section.id='return-responsible-signature-v148';section.className='checklist-section-v147';section.innerHTML='<div class="checklist-section-head-v147"><span>3</span><div><h3>Firma pendiente del Responsable asignado</h3><p>Si la firma no se realizó al momento de la salida, puede completarse antes de cerrar el regreso.</p></div></div><div class="signature-box-v147"><div class="signature-title-v147"><span>Firma del Responsable asignado</span><button type="button" id="return-responsible-clear-v148">Limpiar</button></div><canvas id="return-responsible-canvas-v148" class="signature-canvas-v147"></canvas></div><button type="button" id="return-responsible-save-v148" class="crm-secondary mt-3">Guardar firma pendiente</button>';const actions=form.querySelector('.sticky-modal-actions-v147');form.insertBefore(section,actions);returnResponsiblePadV148=makeSignaturePadV148($('return-responsible-canvas-v148'));$('return-responsible-clear-v148').addEventListener('click',()=>returnResponsiblePadV148?.clear());$('return-responsible-save-v148').addEventListener('click',savePendingResponsibleV148)}const pending=!clean(trip?.responsableFirma);section.classList.toggle('hidden',!pending);if(pending)setTimeout(()=>returnResponsiblePadV148?.resize(),70)}
async function savePendingResponsibleV148(){if(!pendingReturnTripV148)return;const sig=returnResponsiblePadV148?.data()||'';if(!dataUrlValidV148(sig))return alert('Captura la firma del Responsable asignado.');try{const updated=await window.SkilledDB.signVehicleTripResponsible(pendingReturnTripV148.id,sig,{nombre:pendingReturnTripV148.responsableNombre,empresa:pendingReturnTripV148.responsableEmpresa});pendingReturnTripV148=updated||pendingReturnTripV148;ensureReturnResponsibleSignatureV148(pendingReturnTripV148);alert('Firma del Responsable asignado guardada. Ya puedes cerrar el regreso.')}catch(error){alert(error.message||'No se pudo guardar la firma.')}}
